def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return float(min(budget, 18.0))

    prev_bids = []
    threatening_prev = 0.0
    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) > threatening_prev:
                threatening_prev = float(bid)

    # Estimate competition for limited units
    units = int(supply // WATER_REQ)
    alive_count = len(alive)
    scarcity = units <= 1 or supply <= 16
    abundant = supply >= 24

    # Identify likely serious competitor from yesterday traces
    eric_bid = None
    for agent_id, opp in alive:
        if agent_id == 'Eric':
            prev = opp.get('previous_trace', {}) or {}
            if prev.get('bid') is not None:
                eric_bid = float(prev.get('bid'))

    base = 22.0
    if eric_bid is not None:
        base = eric_bid + 2.0
    elif threatening_prev > 0:
        base = min(threatening_prev + 2.0, 78.0)

    # Main policy
    if hp <= 2 or no_water >= 2:
        bid = max(base, 92.0)
    elif hp <= 4 or no_water >= 1:
        bid = max(base, 72.0 if scarcity else 58.0)
    else:
        if scarcity:
            bid = max(base, 64.0)
        elif abundant:
            bid = 26.0 if alive_count >= 2 else 18.0
        else:
            bid = max(34.0, min(base, 68.0))

    # Avoid wasting budget late if healthy
    day = day_context['day']
    if day >= 8 and hp >= 6 and no_water == 0:
        bid = min(bid, 48.0 if not scarcity else 62.0)

    # If only one meaningful rival remains, slightly undercut expensive wars when healthy
    active_threats = 0
    for agent_id, opp in alive:
        if opp.get('budget', 0) > 0 and opp.get('hp', 0) > 0:
            active_threats += 1
    if active_threats <= 1 and hp >= 5 and no_water == 0:
        bid = min(bid, 38.0 if not scarcity else 58.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace to infer aggressiveness.
    yesterday_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate how aggressively others bid: Cindy hit 150 and survived 10 days; Eric bid ~105.
    # Use the maximum yesterday bid as a proxy for current-day pressure.
    pressure = 0.0
    if yesterday_bids:
        pressure = max(yesterday_bids)

    # Base target: secure water at mid-high bids, but avoid matching Cindy's apparent 150-maxing.
    # Scale with supply: if supply is tighter, bid more.
    # supply_ratio near 0 means tight (15), near 1 means abundant (25)
    denom = (MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        supply_ratio = 0.5
    else:
        supply_ratio = (supply - MIN_SUPPLY) / denom
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Tight supply -> raise bid; abundant -> lower.
    tightness_factor = 1.25 - 0.5 * supply_ratio  # ~1.25 at 15, ~0.75 at 25

    # HP urgency: if low HP or accumulating no-water days, we must bid more.
    hp_factor = 1.0
    if hp <= 2.0:
        hp_factor = 1.35
    elif hp <= 4.0:
        hp_factor = 1.15

    if no_water_days >= 2:
        hp_factor *= 1.15

    # Determine bid ceiling based on observed pressure.
    # If someone previously maxed high, we undercut slightly rather than chase.
    # If pressure is low, bid moderately.
    if pressure >= 140.0:
        target = 105.0 * tightness_factor * hp_factor
    elif pressure >= 90.0:
        target = 85.0 * tightness_factor * hp_factor
    else:
        target = 65.0 * tightness_factor * hp_factor

    # Never exceed what we can afford.
    # Also keep a minimum bid to avoid going to zero unless budget is tiny.
    bid = max(0.0, min(budget, target))

    # Safety: if budget is very low, spend most of it to avoid immediate death.
    if budget <= DAILY_SALARY * 0.35:
        bid = max(0.0, min(budget, DAILY_SALARY * 0.9))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if yesterday_bids:
        avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids)
        if avg_opp_bid > 60:
            return min(my_status['budget'], 55.0)
        return min(my_status['budget'], avg_opp_bid + 5.0)

    return min(my_status['budget'], 45.0)
